"""Tic-tac-toe learned with a value table and the temporal-difference rule.

Each board state seen by player X gets a value: the estimated probability of winning
from there (1 = won, 0 = lost or drawn, 0.5 = unknown). X moves greedily most of the
time and explores randomly sometimes; after each greedy move the previous state's value
is nudged toward the new state's value:  V(s) <- V(s) + alpha * [V(s') - V(s)].
"""
import random
random.seed(0)
LINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]
def winner(b):
    for a, c, d in LINES:
        if b[a] != " " and b[a] == b[c] == b[d]: return b[a]
    return "draw" if " " not in b else None

V = {}
def value(b):
    if b not in V:
        w = winner(b)
        V[b] = 1.0 if w == "X" else 0.0 if w in ("O", "draw") else 0.5
    return V[b]

def play(alpha=0.1, eps=0.1, learn=True):
    b, prev = " " * 9, None
    while True:
        moves = [i for i in range(9) if b[i] == " "]
        nxt = [b[:i] + "X" + b[i+1:] for i in moves]
        explore = random.random() < eps
        s2 = random.choice(nxt) if explore else max(nxt, key=value)
        if learn and prev is not None and not explore:       # TD update after greedy moves only
            V[prev] = value(prev) + alpha * (value(s2) - value(prev))
        prev, b = s2, s2
        if winner(b): break
        moves = [i for i in range(9) if b[i] == " "]        # random opponent O
        i = random.choice(moves); b = b[:i] + "O" + b[i+1:]
        if winner(b):
            if learn: V[prev] = value(prev) + alpha * (value(b) - value(prev))
            break
    return winner(b)

def evaluate(n=2000):
    r = [play(eps=0.0, learn=False) for _ in range(n)]
    return {k: round(r.count(k) / n, 3) for k in ("X", "O", "draw")}

print("before learning (greedy on all-0.5 table):", evaluate())
for block in range(1, 6):
    for _ in range(4000): play()
    print(f"after {block*4000:>5} training games:", evaluate(), f"| states in table: {len(V)}")

# the single update used in the worked example
v_s, v_next, alpha = 0.5, 1.0, 0.1
print("\nworked TD update: V(s) =", v_s, "+", alpha, "* (", v_next, "-", v_s, ") =", v_s + alpha * (v_next - v_s))
